function nthSmoothNumber(n: number): number {
  let found = 0;
  for (let x = 1; ; x++) {
    let y = x;
    for (const p of [2, 3, 5]) while (y % p === 0) y /= p;
    if (y === 1 && ++found === n) return x;
  }
}

