function nthSmoothNumber(n: number): number {
  const heap: number[] = [1];
  const seen = new Set<number>([1]);
  const push = (v: number) => {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = (): number => {
    const top = heap[0], last = heap.pop()!;
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };
  let cur = 1;
  for (let k = 0; k < n; k++) {
    cur = pop();
    for (const f of [2, 3, 5]) {
      const v = cur * f;
      if (!seen.has(v)) { seen.add(v); push(v); }
    }
  }
  return cur;
}

