function nthSmoothNumber(n: number): number {
  const seq = [1];
  let i2 = 0, i3 = 0, i5 = 0;
  while (seq.length < n) {
    const a = seq[i2] * 2, b = seq[i3] * 3, c = seq[i5] * 5;
    const next = Math.min(a, b, c);
    seq.push(next);
    if (a === next) i2++;
    if (b === next) i3++;
    if (c === next) i5++;
  }
  return seq[n - 1];
}

